SELECT FROM product p LEFT JOIN product_category c ON p.category_id = c.id AND c.deleted = 0 WHERE p.deleted = 0
AND p.category_id = #{categoryId}
AND p.name LIKE CONCAT('%', #{name}, '%')
AND p.status = #{status}
AND p.tags LIKE CONCAT('%', #{tags}, '%')
ORDER BY p.sort ASC, p.id DESC

SELECT COUNT(*) FROM product p
WHERE p.deleted = 0
AND p.category_id = #{categoryId}
AND p.name LIKE CONCAT('%', #{name}, '%')
AND p.status = #{status}
AND p.tags LIKE CONCAT('%', #{tags}, '%')

