UPDATE product
SET stock = stock - #{quantity}
WHERE id = #{id} AND deleted = 0 AND stock >= #{quantity}

UPDATE product
SET stock = stock + #{quantity}
WHERE id = #{id} AND deleted = 0

UPDATE product
SET sales = sales + #{quantity}
WHERE id = #{id} AND deleted = 0
